const fs = require('fs');

const data = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
let idx = 0;

const n = data[idx++];
const m = data[idx++];

const containers = [];
for (let i = 0; i < m; i++) {
    const a = data[idx++];
    const b = data[idx++];
    containers.push({ a, b });
}

containers.sort((x, y) => y.b - x.b);

let sum = 0;
let remaining = n;

for (const c of containers) {
    if (remaining <= 0) break;
    const take = Math.min(c.a, remaining);
    sum += take * c.b;
    remaining -= take;
}

console.log(sum);

